const fs = require("fs");
const path = require("path");
const { IOSConfig, withDangerousMod, withXcodeProject } = require("expo/config-plugins");

/**
 * iPhone: compiles the "Add bank message to Arth" Shortcuts action (plugins/ios/
 * AddBankMessageIntent.swift) into the app target. Shortcuts only lists App Intents that are part
 * of the app itself - not ones in a pod or local module - and ios/ is regenerated by prebuild, so
 * the file is copied in and registered on every prebuild. Android is untouched.
 */
const FILE_NAME = "AddBankMessageIntent.swift";

function withBankMessageIntent(config) {
  config = withDangerousMod(config, [
    "ios",
    async (cfg) => {
      const projectName = IOSConfig.XcodeUtils.getProjectName(cfg.modRequest.projectRoot);
      const dest = path.join(cfg.modRequest.platformProjectRoot, projectName, FILE_NAME);
      fs.copyFileSync(path.join(__dirname, "ios", FILE_NAME), dest);
      return cfg;
    },
  ]);
  return withXcodeProject(config, (cfg) => {
    const projectName = IOSConfig.XcodeUtils.getProjectName(cfg.modRequest.projectRoot);
    const filepath = `${projectName}/${FILE_NAME}`;
    if (!cfg.modResults.hasFile(filepath)) {
      IOSConfig.XcodeUtils.addBuildSourceFileToGroup({ filepath, groupName: projectName, project: cfg.modResults });
    }
    return cfg;
  });
}

module.exports = withBankMessageIntent;
